export interface PaletteColor {
  id: string;
  hex: string;
  name?: string;
}

export interface PaletteConfig {
  maxColors?: number;
  showNames?: boolean;
  /** Which export formats are available */
  formats?: ("hex" | "hsl" | "rgb" | "tailwind" | "css-vars")[];
}

export interface PaletteContextValue {
  colors: PaletteColor[];
  selectedId: string | null;
  editingId: string | null;
  config: PaletteConfig;

  select: (id: string | null) => void;
  startEdit: (id: string) => void;
  stopEdit: () => void;
  add: (hex?: string) => void;
  remove: (id: string) => void;
  update: (id: string, patch: Partial<Omit<PaletteColor, "id">>) => void;
  reorder: (colors: PaletteColor[]) => void;
  duplicate: (id: string) => void;
}

export type ExportFormat = "hex-array" | "css-vars" | "tailwind" | "hsl-array";

import { ExportFormat, PaletteColor } from "./palette-types";

export function hexToRgb(hex: string): [number, number, number] {
  const h = hex.replace("#", "");
  return [
    parseInt(h.slice(0, 2), 16),
    parseInt(h.slice(2, 4), 16),
    parseInt(h.slice(4, 6), 16),
  ];
}

export function rgbToHex(r: number, g: number, b: number): string {
  return (
    "#" +
    [r, g, b]
      .map((v) =>
        Math.round(Math.max(0, Math.min(255, v)))
          .toString(16)
          .padStart(2, "0"),
      )
      .join("")
  );
}

export function rgbToHsv(
  r: number,
  g: number,
  b: number,
): [number, number, number] {
  r /= 255;
  g /= 255;
  b /= 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const d = max - min;
  let h = 0;
  if (d !== 0) {
    if (max === r) h = ((g - b) / d + (g < b ? 6 : 0)) / 6;
    else if (max === g) h = ((b - r) / d + 2) / 6;
    else h = ((r - g) / d + 4) / 6;
  }
  return [
    Math.round(h * 360),
    Math.round(max === 0 ? 0 : (d / max) * 100),
    Math.round(max * 100),
  ];
}

export function hsvToRgb(
  h: number,
  s: number,
  v: number,
): [number, number, number] {
  s /= 100;
  v /= 100;
  const k = (n: number) => (n + h / 60) % 6;
  const f = (n: number) =>
    v * (1 - s * Math.max(0, Math.min(k(n), 4 - k(n), 1)));
  return [
    Math.round(f(5) * 255),
    Math.round(f(3) * 255),
    Math.round(f(1) * 255),
  ];
}

export function hexToHsv(hex: string): [number, number, number] {
  return rgbToHsv(...hexToRgb(hex));
}

export function hsvToHex(h: number, s: number, v: number): string {
  return rgbToHex(...hsvToRgb(h, s, v));
}

export function hexToHsl(hex: string): [number, number, number] {
  const [r, g, b] = hexToRgb(hex).map((v) => v / 255) as [
    number,
    number,
    number,
  ];
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;
  if (max === min) return [0, 0, Math.round(l * 100)];
  const d = max - min;
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
  let h = 0;
  if (max === r) h = ((g - b) / d + (g < b ? 6 : 0)) / 6;
  else if (max === g) h = ((b - r) / d + 2) / 6;
  else h = ((r - g) / d + 4) / 6;
  return [Math.round(h * 360), Math.round(s * 100), Math.round(l * 100)];
}

export function getContrastColor(hex: string): "#000000" | "#ffffff" {
  const [r, g, b] = hexToRgb(hex);
  const lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return lum > 0.55 ? "#000000" : "#ffffff";
}

export function normalizeHex(raw: string): string | null {
  const h = raw.trim().replace(/^#/, "");
  if (h.length === 3) {
    const expanded = h
      .split("")
      .map((c) => c + c)
      .join("");
    return `#${expanded.toLowerCase()}`;
  }
  if (h.length === 6 && /^[0-9a-fA-F]{6}$/.test(h)) {
    return `#${h.toLowerCase()}`;
  }
  return null;
}

export function toHslString(hex: string): string {
  const [h, s, l] = hexToHsl(hex);
  return `hsl(${h}, ${s}%, ${l}%)`;
}

export function toRgbString(hex: string): string {
  const [r, g, b] = hexToRgb(hex);
  return `rgb(${r}, ${g}, ${b})`;
}

const FILE_EXTENSIONS: Record<ExportFormat, string> = {
  "hex-array": "json",
  "hsl-array": "json",
  "css-vars": "css",
  tailwind: "js",
};

export function generateColor(
  format: ExportFormat,
  colors: PaletteColor[],
): string {
  if (colors.length === 0) return "";
  switch (format) {
    case "hex-array":
      return JSON.stringify(
        colors.map((c) => c.hex),
        null,
        2,
      );

    case "hsl-array":
      return JSON.stringify(
        colors.map((c) => {
          const [h, s, l] = hexToHsl(c.hex);
          return `hsl(${h}, ${s}%, ${l}%)`;
        }),
        null,
        2,
      );

    case "css-vars": {
      const lines = colors.map((c, i) => {
        const name = c.name
          ? c.name.toLowerCase().replace(/\s+/g, "-")
          : `color-${i + 1}`;
        return `  --color-${name}: ${c.hex};`;
      });
      return `:root {\n${lines.join("\n")}\n}`;
    }

    case "tailwind": {
      const entries = colors.map((c, i) => {
        const name = c.name
          ? `"${c.name.toLowerCase().replace(/\s+/g, "-")}"`
          : `"color-${i + 1}"`;
        return `  ${name}: "${c.hex}",`;
      });
      return `// tailwind.config.js\ncolors: {\n${entries.join("\n")}\n}`;
    }
    default: {
      return "";
    }
  }
}

export function downloadColor(format: ExportFormat, colors: PaletteColor[]) {
  const text = generateColor(format, colors);
  if (!text) return;

  const ext = FILE_EXTENSIONS[format];
  const blob = new Blob([text], { type: "text/plain" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `palette-${format}.${ext}`;
  a.click();
  URL.revokeObjectURL(url);
}

import * as React from "react";
import type { PaletteContextValue } from "./palette-types";

export const PaletteCtx = React.createContext<PaletteContextValue | null>(null);

export function usePalette(): PaletteContextValue {
  const ctx = React.useContext(PaletteCtx);
  if (!ctx) throw new Error("usePalette must be used inside PaletteRoot");
  return ctx;
}

import * as React from "react";
import { PaletteCtx } from "./palette-context";
import { PaletteGrid } from "./palette-grid";
import { PaletteToolbar } from "./palette-toolbar";
import { PaletteColorEditor } from "./palette-color-editor";
import { normalizeHex } from "./palette-utils";
import type {
  PaletteColor,
  PaletteConfig,
  PaletteContextValue,
} from "./palette-types";
import { cn } from "@/lib/utils";

let _id = 0;
function uid() {
  return `pc_${++_id}`;
}

export interface PaletteRootProps {
  /** Initial colors. Each must have id + hex. */
  defaultColors?: PaletteColor[];
  /** Controlled colors — pair with onChange */
  colors?: PaletteColor[];
  onChange?: (colors: PaletteColor[]) => void;
  config?: PaletteConfig;
  /** Replace the default layout entirely */
  children?: React.ReactNode;
  className?: string;
}

export function PaletteRoot({
  defaultColors = [],
  colors: controlled,
  onChange,
  config = {},
  children,
  className,
}: PaletteRootProps) {
  const [internal, setInternal] = React.useState<PaletteColor[]>(
    controlled ?? defaultColors,
  );
  const [selectedId, setSelectedId] = React.useState<string | null>(null);
  const [editingId, setEditingId] = React.useState<string | null>(null);

  const colors = controlled ?? internal;

  function commit(next: PaletteColor[]) {
    if (!controlled) setInternal(next);
    onChange?.(next);
  }

  const ctx: PaletteContextValue = {
    colors,
    selectedId,
    editingId,
    config,

    select: (id) => setSelectedId(id),
    startEdit: (id) => {
      setSelectedId(id);
      setEditingId(id);
    },
    stopEdit: () => setEditingId(null),

    add: (hex = "#c2f13c") => {
      if (config.maxColors && colors.length >= config.maxColors) return;
      const color: PaletteColor = { id: uid(), hex: normalizeHex(hex) ?? hex };
      const next = [...colors, color];
      commit(next);
      setSelectedId(color.id);
      setEditingId(color.id);
    },

    remove: (id) => {
      commit(colors.filter((c) => c.id !== id));
      if (selectedId === id) setSelectedId(null);
      if (editingId === id) setEditingId(null);
    },

    update: (id, patch) => {
      commit(colors.map((c) => (c.id === id ? { ...c, ...patch } : c)));
    },

    reorder: (next) => commit(next),
    duplicate: (id) => {
      const src = colors.find((c) => c.id === id);
      if (!src) return;
      const copy: PaletteColor = {
        id: uid(),
        hex: src.hex,
        name: src.name ? `${src.name} copy` : undefined,
      };
      const idx = colors.findIndex((c) => c.id === id);
      const next = [...colors];
      next.splice(idx + 1, 0, copy);
      commit(next);
      setSelectedId(copy.id);
    },
  };

  return (
    <PaletteCtx.Provider value={ctx}>
      {children ?? (
        <div className={cn("flex flex-col gap-3", className)}>
          <PaletteToolbar />
          <div className="flex gap-4 items-start">
            <PaletteGrid />
            <PaletteColorEditor />
          </div>
        </div>
      )}
    </PaletteCtx.Provider>
  );
}

PaletteRoot.displayName = "PaletteRoot";

import { SortableRoot, SortableItem, SortableHandle } from "../sortable";
import { PaletteSwatch } from "./palette-swatch";
import { usePalette } from "./palette-context";
import { cn } from "@/lib/utils";

export interface PaletteGridProps {
  className?: string;
}

export function PaletteGrid({ className }: PaletteGridProps) {
  const { colors, reorder } = usePalette();

  return (
    <SortableRoot
      items={colors}
      onReorder={reorder}
      config={{ layout: "grid" }}
      renderOverlay={(c) => (
        <PaletteSwatch id={c.id} className="opacity-90 shadow-xl scale-105 " />
      )}
    >
      <div
        className={cn(
          "grid gap-1.5",
          "grid-cols-[repeat(auto-fill,minmax(36px,1fr))]",
          "p-2 rounded-lg border border-border bg-card/80 min-w-[220px]",
          className,
        )}
      >
        {colors.map((c) => (
          <SortableItem key={c.id} id={c.id} handle>
            <div className="relative group">
              <PaletteSwatch id={c.id} />
              <SortableHandle className="absolute -top-1 -right-1 opacity-0 group-hover:opacity-100 w-4 h-5 p-0 bg-background text-foreground rounded-sm border border-border flex items-center justify-center transition-opacity" />
            </div>
          </SortableItem>
        ))}
      </div>
    </SortableRoot>
  );
}

PaletteGrid.displayName = "PaletteGrid";

import { cn } from "@/lib/utils";
import { usePalette } from "./palette-context";
import { getContrastColor } from "./palette-utils";

export interface PaletteSwatchProps {
  id: string;
  className?: string;
}

export function PaletteSwatch({ id, className }: PaletteSwatchProps) {
  const { colors, selectedId, editingId, select, startEdit } = usePalette();
  const color = colors.find((c) => c.id === id);
  if (!color) return null;

  const isSelected = selectedId === id;
  const isEditing = editingId === id;
  const textColor = getContrastColor(color.hex);

  return (
    <button
      type="button"
      title={color.name ?? color.hex}
      onClick={() => select(id)}
      onDoubleClick={() => startEdit(id)}
      className={cn(
        "w-9 h-9 rounded-sm border-2 transition-all focus-visible:outline-none",
        "focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-1",
        isSelected
          ? "border-primary/50 scale-110 shadow-md z-10"
          : "border-transparent hover:scale-105 hover:border-border",
        isEditing && "ring-2 ring-primary/20 ring-offset-1",
        className,
      )}
      style={{ backgroundColor: color.hex }}
      aria-pressed={isSelected}
      aria-label={color.name ?? color.hex}
    />
  );
}

PaletteSwatch.displayName = "PaletteSwatch";

import * as React from "react";
import { usePalette } from "./palette-context";
import {
  hexToHsv,
  hsvToHex,
  normalizeHex,
  toHslString,
  toRgbString,
} from "./palette-utils";
import { cn } from "@/lib/utils";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

interface SatValPickerProps {
  hue: number;
  sat: number;
  val: number;
  onChange: (s: number, v: number) => void;
}

function SatValPicker({ hue, sat, val, onChange }: SatValPickerProps) {
  const ref = React.useRef<HTMLDivElement>(null);

  function read(e: React.PointerEvent) {
    const rect = ref.current!.getBoundingClientRect();
    const x = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    const y = Math.max(0, Math.min(1, (e.clientY - rect.top) / rect.height));
    onChange(Math.round(x * 100), Math.round((1 - y) * 100));
  }

  return (
    <div
      ref={ref}
      className="relative w-full h-36 rounded-lg cursor-crosshair select-none overflow-hidden"
      style={{
        background: `
          linear-gradient(to top, #000, transparent),
          linear-gradient(to right, #fff, hsl(${hue}, 100%, 50%))
        `,
      }}
      onPointerDown={(e) => {
        e.currentTarget.setPointerCapture(e.pointerId);
        read(e);
      }}
      onPointerMove={(e) => {
        if (e.buttons === 1) read(e);
      }}
    >
      <div
        className="absolute w-3.5 h-3.5 rounded-full border-2 border-white pointer-events-none -translate-x-1/2 -translate-y-1/2"
        style={{
          left: `${sat}%`,
          top: `${100 - val}%`,
          boxShadow: "0 0 0 1px rgba(0,0,0,0.4), 0 1px 3px rgba(0,0,0,0.3)",
        }}
      />
    </div>
  );
}

function HueSlider({
  hue,
  onChange,
}: {
  hue: number;
  onChange: (h: number) => void;
}) {
  const ref = React.useRef<HTMLDivElement>(null);

  function read(e: React.PointerEvent) {
    const rect = ref.current!.getBoundingClientRect();
    const x = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    onChange(Math.round(x * 360));
  }

  return (
    <div
      ref={ref}
      className="relative h-3 rounded-full cursor-pointer select-none"
      style={{
        background:
          "linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00)",
      }}
      onPointerDown={(e) => {
        e.currentTarget.setPointerCapture(e.pointerId);
        read(e);
      }}
      onPointerMove={(e) => {
        if (e.buttons === 1) read(e);
      }}
    >
      <div
        className="absolute top-1/2 w-4 h-4 rounded-full border-2 border-white pointer-events-none -translate-x-1/2 -translate-y-1/2"
        style={{
          left: `${(hue / 360) * 100}%`,
          background: `hsl(${hue}, 100%, 50%)`,
          boxShadow: "0 0 0 1px rgba(0,0,0,0.3)",
        }}
      />
    </div>
  );
}

export function PaletteColorEditor() {
  const { colors, editingId, update, stopEdit } = usePalette();
  const color = colors.find((c) => c.id === editingId);

  const [hsv, setHsv] = React.useState<[number, number, number]>(() =>
    color ? hexToHsv(color.hex) : [0, 0, 100],
  );
  const [hexInput, setHexInput] = React.useState(color?.hex ?? "#ffffff");
  const [nameInput, setNameInput] = React.useState(color?.name ?? "");

  React.useEffect(() => {
    if (!color) return;
    setHsv(hexToHsv(color.hex));
    setHexInput(color.hex);
    setNameInput(color.name ?? "");
  }, [editingId]);

  const [h, s, v] = hsv;
  const previewHex = hsvToHex(h, s, v);

  function applyHsv(next: [number, number, number]) {
    setHsv(next);
    const hex = hsvToHex(...next);
    setHexInput(hex);
    update(editingId!, { hex });
  }

  function handleHexInput(raw: string) {
    setHexInput(raw);
    const norm = normalizeHex(raw);
    if (norm) {
      setHsv(hexToHsv(norm));
      update(editingId!, { hex: norm });
    }
  }

  function handleName(name: string) {
    setNameInput(name);
    update(editingId!, { name: name || undefined });
  }

  return (
    <Popover open={!!color || !!editingId} onOpenChange={stopEdit}>
      <PopoverTrigger />
      <PopoverContent align="start">
        <div className="flex flex-col gap-4 ">
          <div className="flex items-center justify-between">
            <span>Edit color</span>
          </div>

          <SatValPicker
            hue={h}
            sat={s}
            val={v}
            onChange={(ns, nv) => applyHsv([h, ns, nv])}
          />

          <HueSlider hue={h} onChange={(nh) => applyHsv([nh, s, v])} />

          <div className="flex items-center gap-2">
            <div
              className="w-9 h-9 rounded-md border border-border shrink-0"
              style={{ backgroundColor: previewHex }}
            />
            <Input
              value={hexInput}
              onChange={(e) => handleHexInput(e.target.value)}
              className={cn(
                "flex-1 h-9 px-2 rounded-md bg-muted/50 border border-border",
                "text-[12px]  text-foreground outline-none",
                "focus:ring-1 focus:ring-primary transition",
              )}
              spellCheck={false}
              aria-label="Hex value"
            />
          </div>

          <Input
            value={nameInput}
            onChange={(e) => handleName(e.target.value)}
            placeholder="Color name (optional)"
            className={cn(
              "h-9 px-2 rounded-md bg-muted/50 border border-border",
              "text-[12px] text-foreground outline-none placeholder:text-muted-foreground/40",
              "focus:ring-1 focus:ring-primary transition",
            )}
          />

          <div className="flex flex-col gap-1.5 pt-1 border-t border-border/60">
            {[
              { label: "HEX", value: previewHex },
              { label: "HSL", value: toHslString(previewHex) },
              { label: "RGB", value: toRgbString(previewHex) },
            ].map(({ label, value }) => (
              <div
                key={label}
                className="flex items-center justify-between gap-2"
              >
                <span className="text-xs   w-8 shrink-0">{label}</span>
                <button
                  type="button"
                  onClick={() => navigator.clipboard.writeText(value)}
                  className="relative text-xs  hover:text-foreground text-right truncate transition-all p-1 px-2 rounded-full border border-border ease-out z-0"
                  title={`Copy ${value}`}
                >
                  <div
                    style={{ backgroundColor: value }}
                    className=" absolute inset-0 opacity-20 -z-1"
                  />
                  {value}
                </button>
              </div>
            ))}
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

PaletteColorEditor.displayName = "PaletteColorEditor";

import * as React from "react";
import { usePalette } from "./palette-context";
import { PaletteExport } from "./palette-export";
import {
  IconPlus,
  IconTrash,
  IconCopy,
  IconEdit,
  IconDownload,
} from "@tabler/icons-react";
import { Button } from "@/components/ui/button";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Separator } from "@/components/ui/separator";

interface ToolbarButtonProps extends Omit<
  React.ComponentPropsWithoutRef<typeof Button>,
  "children"
> {
  icon: React.ElementType;
  label: string;
}

function ToolbarButton({
  icon: Icon,
  label,
  variant = "ghost",
  size = "sm",
  ...props
}: ToolbarButtonProps) {
  return (
    <Button
      title={label}
      aria-label={label}
      variant={variant}
      size={size}
      {...props}
    >
      <Icon size={13} strokeWidth={1.8} className="shrink-0" />
      {label}
    </Button>
  );
}

export function PaletteToolbar() {
  const { selectedId, add, remove, duplicate, startEdit, config, colors } =
    usePalette();
  const atMax = !!(config.maxColors && colors.length >= config.maxColors);

  return (
    <div className="flex items-center gap-1 px-1 py-1 rounded-lg border border-border bg-card/80 w-fit">
      <ToolbarButton
        icon={IconPlus}
        label="Add color"
        onClick={() => add()}
        disabled={atMax}
      />
      <ToolbarButton
        icon={IconEdit}
        label="Edit"
        onClick={() => selectedId && startEdit(selectedId)}
        disabled={!selectedId}
      />
      <ToolbarButton
        icon={IconCopy}
        label="Duplicate"
        onClick={() => selectedId && duplicate(selectedId)}
        disabled={!selectedId || atMax}
      />
      <Separator orientation="vertical" />
      <ToolbarButton
        icon={IconTrash}
        label="Delete"
        onClick={() => selectedId && remove(selectedId)}
        disabled={!selectedId}
      />
      <Separator orientation="vertical" />
      <Popover>
        <PopoverTrigger>
          <ToolbarButton label="Export" icon={IconDownload} />
        </PopoverTrigger>
        <PopoverContent align="start">
          <PaletteExport />
        </PopoverContent>
      </Popover>
    </div>
  );
}

PaletteToolbar.displayName = "PaletteToolbar";

import * as React from "react";
import { usePalette } from "./palette-context";
import { downloadColor, generateColor, hexToHsl } from "./palette-utils";
import { IconDownload, IconCopy, IconCopyCheck } from "@tabler/icons-react";

import { Button } from "@/components/ui/button";
import { ExportFormat } from "./palette-types";

const FORMAT_LABELS: Record<ExportFormat, string> = {
  "hex-array": "Hex array",
  "css-vars": "CSS variables",
  tailwind: "Tailwind config",
  "hsl-array": "HSL array",
};

export function PaletteExport() {
  const { colors } = usePalette();
  const [format, setFormat] = React.useState<ExportFormat>("hex-array");
  const [copied, setCopied] = React.useState(false);

  function copy() {
    const text = generateColor(format, colors);
    if (!text) return;
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  return (
    <>
      <div className="flex flex-col gap-1">
        {(Object.keys(FORMAT_LABELS) as ExportFormat[]).map((f) => (
          <Button
            key={f}
            onClick={() => setFormat(f)}
            variant={format === f ? "outline" : "ghost"}
            className={"justify-start"}
          >
            {FORMAT_LABELS[f]}
          </Button>
        ))}
      </div>

      <pre className=" bg-muted/40 rounded-lg p-2 overflow-x-auto max-h-32 border border-border/60">
        {generateColor(format, colors) || "No colors"}
      </pre>
      <div className="flex gap-2">
        <Button
          onClick={copy}
          variant={copied ? "outline" : "secondary"}
          className="flex-1"
        >
          {copied ? (
            <>
              <IconCopyCheck size={12} /> Copied
            </>
          ) : (
            <>
              <IconCopy size={12} /> Copy
            </>
          )}
        </Button>
        <Button
          onClick={() => downloadColor(format, colors)}
          variant={copied ? "outline" : "secondary"}
          className="flex-1"
        >
          <IconDownload size={12} /> Download
        </Button>
      </div>
    </>
  );
}

